package com.example.agendapersonal.ui;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.widget.*;import android.view.View;
import com.example.agendapersonal.R;import com.example.agendapersonal.ui.registro.*;
import java.time.LocalDate;import java.util.*;
public class EconomiaActivity extends com.example.agendapersonal.ui.ActividadTematica {
 private MenuNavegacion menu;private Spinner periodo;
 @Override protected void onCreate(Bundle s){super.onCreate(s);menu=new MenuNavegacion(this);setContentView(menu.getRaiz());menu.establecerContenido(R.layout.activity_economia);findViewById(R.id.botonMenu).setOnClickListener(v->menu.alternar());periodo=findViewById(R.id.periodoEconomia);ArrayAdapter<String>a=new ArrayAdapter<>(this,com.example.agendapersonal.R.layout.item_opcion_tema,new String[]{"Este mes","Este año","Todo el historial"});periodo.setAdapter(a);periodo.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?>p,View v,int n,long id){cargar();}public void onNothingSelected(android.widget.AdapterView<?>p){}});int[] ids={R.id.abrirIngresos,R.id.abrirPagos,R.id.abrirGastos};for(int i=0;i<3;i++){final int seccion=i;findViewById(ids[i]).setOnClickListener(v->startActivity(new Intent(this,MovimientosActivity.class).putExtra("seccionInicial",seccion)));}}
 @Override protected void onResume(){super.onResume();if(periodo!=null)cargar();}
 private void cargar(){String device=getSharedPreferences("agenda_identidad",MODE_PRIVATE).getString("device_id","");LocalDate hoy=LocalDate.now(),desde=periodo.getSelectedItemPosition()==0?hoy.withDayOfMonth(1):periodo.getSelectedItemPosition()==1?hoy.withDayOfYear(1):LocalDate.MIN;SortedMap<LocalDate,double[]>series=new TreeMap<>();java.math.BigDecimal[]totales={java.math.BigDecimal.ZERO,java.math.BigDecimal.ZERO,java.math.BigDecimal.ZERO};String[]tablas={"ingresos","pagos","gastos"};try{for(int i=0;i<3;i++){try(Fuente f=Fuentes.abrir(this,device,tablas[i])){for(Registro r:f.todos())if("FINALIZADO".equals(r.texto("estadoEspecial"))&&!r.texto("fecha").isEmpty()){LocalDate fecha=LocalDate.parse(r.texto("fecha"));if(fecha.isBefore(desde)||fecha.isAfter(hoy))continue;java.math.BigDecimal importe=new java.math.BigDecimal(r.texto("importe"));series.computeIfAbsent(fecha,k->new double[3])[i]+=importe.doubleValue();totales[i]=totales[i].add(importe);}}}((GraficoLineasView)findViewById(R.id.graficoEconomia)).datos(series);((TextView)findViewById(R.id.resumenEconomia)).setText("Movimientos finalizados\nIngresos: "+totales[0].toPlainString()+"\nPagos: "+totales[1].toPlainString()+"\nGastos: "+totales[2].toPlainString()+"\nBalance: "+totales[0].subtract(totales[1]).subtract(totales[2]).toPlainString());}catch(RuntimeException e){Toast.makeText(this,"No se pudo cargar el resumen de economía",Toast.LENGTH_LONG).show();android.util.Log.e("AgendaPersonal","Economía",e);}}
 @Override public void onBackPressed(){if(menu.estaAbierto())menu.cerrar();else super.onBackPressed();}
}
